inline constexpr char kPathPayFor[] = "/api/v1/device/pay-for";

/// Everything one pay-for request names. A struct for the reason WalkUpRequest
/// is one: seven fields, two of them small integers that swap silently.
struct PayForRequest {
  const char* mac = nullptr;
  /// What the scanner read, verbatim: who is paying.
  const char* token = nullptr;
  /// The CLUB court number of the pressed relay, never the relay index.
  int16_t courtNumber = 0;
  /// The 16-hex nonce of this quote, carried by its confirm.
  const char* nonce = nullptr;
  bool confirm = false;
  /// The label the glass showed — confirm only.
  const char* amountLabel = nullptr;
  /// Milliseconds since the scan. Rendered only for a v1 member code: the
  /// server verifies its ON half at the instant it was read, not the instant
  /// the second button went down. A legacy code's body is unchanged.
  uint32_t scanAgeMs = 0U;
};

/// Renders the pay-for body in the corpus's field order: mac, method, token,
/// court, nonce, confirm, [amount_label], [scan_age_ms]. 0 — never a truncated
/// body — when it does not fit or a field is missing.
size_t renderPayForBody(char* out, size_t cap, const PayForRequest& request);

/// What an answer means.
enum class PayForKind : uint8_t {
  /// A confirm that got no decision: keep the quote and its nonce.
  Undecided = 0U,
  /// Not a pay-for after all: carry on as the walk-up court choice.
  WalkUp = 1U,
  /// The quote is armed; paint PayForQuote and wait for the second press.
  Quote = 2U,
  /// Paid.
  Paid = 3U,
  /// A decided refusal; paint `screen`.
  Refused = 4U,
};

struct PayForAnswer {
  PayForKind kind = PayForKind::WalkUp;
  /// What to paint for Quote, Paid, Refused and Undecided.
  ScreenId screen = ScreenId::SeeTheDesk;
  /// The label to show and, for a quote, to echo on the confirm.
  char amountLabel[kMaxAmountLabelLen + 1U] = {};
  /// On Paid: seconds to light the court for, 0 when it is already lit or the
  /// server grants nothing.
  uint32_t grantedSeconds = 0U;
};

/// A label the glass can show honestly: one to six characters, digits with at
/// most one `.` that is neither first nor last and has one or two digits after
/// it. Anything else is refused, never cut.
bool validAmountLabel(const char* label);

/// Interprets the answer to a QUOTE for the court numbered `courtNumber`.
///
///   200 payable:true, court_number == courtNumber, a valid amount_label -> Quote
///   200 payable:false, reason not_booked                                  -> WalkUp
///   200 payable:false, any other reason                                   -> Refused
///   anything else, including a payable:true the glass cannot show          -> WalkUp
PayForAnswer onPayForQuote(uint16_t status, const char* body, size_t len, int16_t courtNumber);

/// Interprets the answer to a CONFIRM.
///
///   0, 429, 5xx, or a 200 that cannot be read -> Undecided (retry = same nonce)
///   200 paid:true                              -> Paid, granted_seconds if any
///   200 paid:false                             -> Refused, by reason
///   any other status                           -> Refused, SEE THE DESK
PayForAnswer onPayForConfirm(uint16_t status, const char* body, size_t len, const char* quotedLabel);

/// The state between the two presses: which relay was quoted, at what label,
/// under which nonce, until when.
class PayForFlow {
public:
  /// True while a quote for `relay` is armed and unexpired.
  bool quoted(uint8_t relay, uint32_t nowMs) const;

  /// Draws a FRESH nonce for a quote request and returns it. The quote that
  /// comes back is armed under it (arm), and its confirm and every undecided
  /// retry of that confirm carry the same one.
  const char* quoteNonce(devapi::IEntropySource& entropy);

  /// Arms the quote just answered, under the nonce quoteNonce drew for it.
  void arm(uint8_t relay, int16_t courtNumber, const char* amountLabel, uint32_t ttlMs, uint32_t nowMs);

  /// True exactly once, on the pass an armed quote lapsed.
  bool tick(uint32_t nowMs);

  void clear();

  uint8_t relay() const { return relay_; }

  int16_t courtNumber() const { return courtNumber_; }

  const char* amountLabel() const { return label_; }

  const char* nonce() const { return nonce_; }

private:
  char nonce_[kWalkUpNonceHexLen + 1U] = {};
  char label_[kMaxAmountLabelLen + 1U] = {};
  uint8_t relay_ = 0U;
  int16_t courtNumber_ = 0;
  tb::Deadline until_;
};

